        q2: ["html", "css"],
        q3: ["sql", "r"]
      };

      function getSelectedValues(questionName) {
        return Array.from(
          quizForm.querySelectorAll(`input[name="${questionName}"]:checked`),
          (input) => input.value
        ).sort();
      }

      function arraysMatch(first, second) {
        return first.length === second.length && first.every((value, index) => value === second[index]);
      }

      quizForm.addEventListener("submit", (event) => {
        event.preventDefault();

        let score = 0;
        let answeredQuestions = 0;
        const totalQuestions = Object.keys(correctAnswers).length;

        for (const [questionName, answers] of Object.entries(correctAnswers)) {
          const selectedValues = getSelectedValues(questionName);
          if (selectedValues.length > 0) {
            answeredQuestions += 1;
          }

          if (arraysMatch(selectedValues, answers)) {
            score += 1;
          }
        }

        result.classList.remove("is-error", "is-success");

        if (answeredQuestions < totalQuestions) {
          result.textContent = "Please answer every question before submitting.";
          result.classList.add("is-error");
          const firstUnanswered = Object.keys(correctAnswers).find(
            (questionName) => getSelectedValues(questionName).length === 0
          );
          quizForm.querySelector(`input[name="${firstUnanswered}"]`).focus();
          return;
        }

        result.textContent = `You scored ${score} out of ${totalQuestions}.`;
        result.classList.add("is-success");
