+
+      function getSelectedValues(questionName) {
+        return Array.from(
+          quizForm.querySelectorAll(`input[name="${questionName}"]:checked`),
+          (input) => input.value
+        ).sort();
+      }
+
+      function arraysMatch(first, second) {
+        return first.length === second.length && first.every((value, index) => value === second[index]);
+      }
+
+      quizForm.addEventListener("submit", (event) => {
+        event.preventDefault();
+
+        let score = 0;
+        let answeredQuestions = 0;
+        const totalQuestions = Object.keys(correctAnswers).length;
+
+        for (const [questionName, answers] of Object.entries(correctAnswers)) {
+          const selectedValues = getSelectedValues(questionName);
+          if (selectedValues.length > 0) {
